// ========== Format Financial Summary ==========

const items = $input.all();

// Get Yahoo Finance data (first input)
const yahooData = items[0]?.json?.quoteResponse?.result || items[0]?.json || [];

// Get CoinGecko data (second input)
let cryptoData = {};
for (const item of items) {
  if (item.json?.bitcoin || item.json?.ethereum) {
    cryptoData = item.json;
    break;
  }
}

// If yahooData is a single object (from merge), try to extract
let quotes = [];
if (Array.isArray(yahooData)) {
  quotes = yahooData;
} else if (yahooData?.quoteResponse?.result) {
  quotes = yahooData.quoteResponse.result;
}

// Build quote map
const quoteMap = {};
for (const q of quotes) {
  if (q?.symbol) {
    quoteMap[q.symbol] = {
      price: q.regularMarketPrice,
      change: q.regularMarketChangePercent,
    };
  }
}

// Helper functions
function fmt(num, dec = 2) {
  if (num == null || isNaN(num)) return 'N/A';
  return Number(num).toLocaleString('en-US', {
    minimumFractionDigits: dec,
    maximumFractionDigits: dec,
  });
}

function arrow(ch) {
  if (ch == null || isNaN(ch)) return '➡️';
  return ch >= 0 ? '📈' : '📉';
}

function chg(ch) {
  if (ch == null || isNaN(ch)) return 'N/A';
  const s = ch >= 0 ? '+' : '';
  return `${s}${ch.toFixed(2)}%`;
}

const days = ['ראשון','שני','שלישי','רביעי','חמישי','שישי','שבת'];
const months = ['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const now = new Date();
const dateStr = `יום ${days[now.getDay()]}, ${now.getDate()} ב${months[now.getMonth()]} ${now.getFullYear()}`;

// Build lines
function line(symbol, name, dec = 2) {
  const q = quoteMap[symbol] || {};
  return `${arrow(q.change)} ${name}: ${fmt(q.price, dec)} (${chg(q.change)})`;
}

function cryptoLine(id, name) {
  const c = cryptoData[id] || {};
  return `${arrow(c.usd_24h_change)} ${name}: ${fmt(c.usd)} (${chg(c.usd_24h_change)})`;
}

const message = `☀️ סקירת בוקר פיננסית
${dateStr}

💱 מט"ח:
${line('USDILS=X', 'דולר/שקל', 3)}
${line('EURILS=X', 'יורו/שקל', 3)}

📊 מדדים:
${line('^IXIC', 'נאסד"ק')}
${line('^GSPC', 'S&P 500')}
${line('^TA35.TA', 'ת"א 35')}
${line('^TA125.TA', 'ת"א 125')}

🏆 סחורות:
${line('GC=F', 'זהב')}
${line('CL=F', 'נפט')}

₿ קריפטו:
${cryptoLine('bitcoin', 'ביטקוין')}
${cryptoLine('ethereum', 'אתריום')}

נוצר אוטומטית | סקירה זו אינה מהווה המלצת השקעה`;

return [{ json: { message, timestamp: new Date().toISOString() } }];
